    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_server_p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.attr_span_kind='Client' AND c.attr_span_kind='Server' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "ts-travel-plan-service calls to route-plan-service see about 23,383 ms server p95, up from about 780 ms."}]},
